/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import BasicCoordinatesAndSeasonsColors from "../../src/BasicCoordinatesAndSeasonsColors.js";
import { CelestialScreen } from "../../src/celestial/CelestialScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { BasicCoordinatesAndSeasonsPreferencesModel } from "../../src/preferences/BasicCoordinatesAndSeasonsPreferencesModel.js";
import { SeasonsScreen } from "../../src/seasons/SeasonsScreen.js";
import { TerrestrialScreen } from "../../src/terrestrial/TerrestrialScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();
  const screenNames = stringManager.getScreenNames();

  // Simulation-specific preferences; initial values come from basicCoordinatesAndSeasonsQueryParameters.
  const simPreferences = new BasicCoordinatesAndSeasonsPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new TerrestrialScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.terrestrialStringProperty,
      tandem: Tandem.ROOT.createTandem("terrestrialScreen"),
      backgroundColorProperty: BasicCoordinatesAndSeasonsColors.backgroundColorProperty,
      earthMapResolutionProperty: simPreferences.earthMapResolutionProperty,
    }),
    new CelestialScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.celestialStringProperty,
      tandem: Tandem.ROOT.createTandem("celestialScreen"),
      backgroundColorProperty: BasicCoordinatesAndSeasonsColors.backgroundColorProperty,
    }),
    new SeasonsScreen({
      // The screen name Property updates automatically when the locale changes
      name: screenNames.seasonsStringProperty,
      tandem: Tandem.ROOT.createTandem("seasonsScreen"),
      backgroundColorProperty: BasicCoordinatesAndSeasonsColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { BasicCoordinatesAndSeasonsColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
